pm.test("Status code should be 200", function () {
    pm.response.to.have.status(200);
});

const users = pm.response.json();

pm.test("Response should be a non-empty array", function () {
    pm.expect(users).to.be.an("array");
    pm.expect(users.length).to.be.above(0);
});

pm.test("Each user should have ID, Name and Email", function () {
    users.forEach(function (user) {
        pm.expect(user.id).to.exist;
        pm.expect(user.name).to.be.a("string").and.not.empty;
        pm.expect(user.email).to.be.a("string").and.not.empty;
    });
});

// Save first user's ID for the next request
if (Array.isArray(users) && users.length > 0) {
    pm.collectionVariables.set("userId", users[0].id);
}

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const user = pm.response.json();
pm.collectionVariables.set("originalPhone", user.phone);

pm.test("Correct user ID returned", function () {
    pm.expect(user.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

pm.test("User name is not empty", function () {
    pm.expect(user.name).to.not.be.empty;
});

pm.test("User email is not empty", function () {
    pm.expect(user.email).to.not.be.empty;
});

// Generate dynamic data
const updatedName = pm.variables.replaceIn("{{$randomFullName}}");
const updatedEmail = pm.variables.replaceIn("{{$randomEmail}}");
const updatedCompanyName = pm.variables.replaceIn("{{$randomCompanyName}}");

// Save generated values
pm.collectionVariables.set("updatedName", updatedName);
pm.collectionVariables.set("updatedEmail", updatedEmail);
pm.collectionVariables.set("updatedCompanyName", updatedCompanyName);

// Validate status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const user = pm.response.json();

// Validate returned ID
pm.test("Returned ID matches saved ID", function () {
    pm.expect(user.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

// Validate phone is not empty
pm.test("Phone is not empty", function () {
    pm.expect(user.phone).to.be.a("string").and.not.empty;
});

// Validate updated name
pm.test("Returned name matches updated name", function () {
    pm.expect(user.name).to.eql(
        pm.collectionVariables.get("updatedName")
    );
});
